import csv
import io


def parse_csv(raw_csv: str):
    previous_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(2**31 - 1)
        reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')
        records = list(reader)
    finally:
        csv.field_size_limit(previous_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    if columns:
        columns[0] = columns[0].removeprefix("\ufeff")

    rows = records[1:]
    width = max([len(columns)] + [len(row) for row in rows])
    used_names = set(columns)
    extra_index = 1

    while len(columns) < width:
        name = "extra_{}".format(extra_index)
        extra_index += 1
        if name not in used_names:
            columns.append(name)
            used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
